#include "mdl_flex_metadata.h"
#include <iostream>
static void put(std::vector<uint8_t>& b,size_t p,uint32_t v){std::memcpy(b.data()+p,&v,4);}
int main(){try{static_assert(sizeof(void*)==8,"x64 required");std::vector<uint8_t>b(440);put(b,0,0x54534449);put(b,4,49);put(b,76,440);put(b,268,1);put(b,272,408);put(b,408,20);put(b,412,22);put(b,416,0xffffffff);put(b,424,0x3f800000);b[428]='t';b[430]='n';auto r=readMdl49FlexMetadata(b);if(r.size()!=1||r[0].name!="n"||r[0].type!="t"||r[0].localIndex!=0||r[0].diskGlobalIndex!=-1||r[0].minBits!=0||r[0].maxBits!=0x3f800000)throw std::runtime_error("valid record failed");unsigned rejected=0;for(unsigned c=0;c<8;++c){auto bad=b;switch(c){case 0:bad.resize(200);break;case 1:put(bad,0,0);break;case 2:put(bad,4,48);break;case 3:put(bad,76,439);break;case 4:put(bad,268,0xffffffff);break;case 5:put(bad,272,439);break;case 6:put(bad,412,0x80000000);break;case 7:put(bad,412,31);bad[439]='x';break;}try{readMdl49FlexMetadata(bad);}catch(const std::runtime_error&){++rejected;}}if(rejected!=8)throw std::runtime_error("malformed data accepted");std::cout<<"MDL flex metadata valid record and 8 malformed cases passed\n";return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
